const PREFIX="icu-atlas-shell:"+new URL(self.registration.scope).pathname+":",CACHE=PREFIX+"floor-1.0.1";
const FILES=["./","index.html","app.js","model.js","config.js","labs.js","walkthrough.js","curriculum.js","atlas.js","plates.js","illustrations.js","studio-content.js","studio-draw.js","studio.js","style.css","atlas.css","studio.css","manifest.webmanifest","assets/cardio.webp","assets/heart.webp","assets/icon-180.png","assets/icon-192.png","assets/icon-512.png","assets/icon.svg","assets/neuro.webp","assets/resp.webp","assets/studio-barrier.webp","assets/studio-breathing.webp","assets/studio-csf.webp","assets/studio-filling.webp","assets/studio-filtration.webp","assets/studio-gas.webp","assets/studio-junction.webp","assets/studio-portal.webp","assets/studio-pressure.webp","assets/studio-seal.webp","assets/studio-tissue.webp","assets/studio-water.webp","resus-content.js","resus-content2.js","resus-draw.js","resus-sims.js","resus.js","resus-play.js","resus.css","floor-ecg.js","floor-meds.js","floor-sim.js","floor.js","floor.css","assets/icon-maskable-512.png"];
// Do not seed a new offline revision from the browser's still-fresh HTTP cache.
self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES.map(f=>new Request(new URL(f,self.registration.scope),{cache:"reload"})))).then(()=>self.skipWaiting()))});
self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith(PREFIX)&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener("fetch",e=>{if(e.request.method!=="GET"||!e.request.url.startsWith(self.registration.scope))return;e.respondWith((async()=>{const c=await caches.open(CACHE);let hit=await c.match(e.request,{ignoreSearch:true});if(hit)return hit;try{return await fetch(e.request)}catch(err){if(e.request.mode==="navigate"){let page=await c.match("index.html");if(page)return page}throw err}})())});